import os, subprocess, stat

print("user:", os.getuid(), os.geteuid())
try:
    import pwd, grp
    print("name:", pwd.getpwuid(os.getuid()).pw_name)
    print("groups:", [g.gr_name for g in grp.getgrall() if os.getgid() in g.gr_gid])
except Exception as e:
    print("pwd/grp err:", e)

# sudo probe
r = subprocess.run(["sudo", "-n", "true"], capture_output=True, text=True)
print("sudo -n true rc:", r.returncode, "stderr:", r.stderr.strip())

# setuid scan
print("\nsetuid binaries:")
for root, dirs, files in os.walk("/"):
    for f in files:
        p = os.path.join(root, f)
        try:
            st = os.lstat(p)
        except OSError:
            continue
        if st.st_mode & stat.S_ISUID:
            print(oct(st.st_mode), st.st_uid, p)

